import unittest
from quota_engine.bytesize import parse_bytes
class T(unittest.TestCase):
    def test_sizes(self):
        self.assertEqual(parse_bytes('7B'), 7)
        self.assertEqual(parse_bytes('2KiB'), 2048)
        self.assertEqual(parse_bytes('3MiB'), 3*1024**2)
        self.assertEqual(parse_bytes('1GiB'), 1024**3)
        for bad in ('-1B','3KB','x'): self.assertRaises(ValueError, parse_bytes, bad)

